-- One external account identity belongs to one user. Two connect callbacks can
-- both insert the same providerId and accountId. Those rows have to go before
-- the unique index, or this migration fails and deploy stops. Keep the earliest
-- row (then the lowest id). The user row stays. Append-only: do not edit this file.
DELETE FROM "account"
WHERE "id" NOT IN (
  SELECT "id" FROM "account" AS "candidate"
  WHERE NOT EXISTS (
    SELECT 1 FROM "account" AS "earlier"
    WHERE "earlier"."providerId" = "candidate"."providerId"
      AND "earlier"."accountId" = "candidate"."accountId"
      AND (
        "earlier"."createdAt" < "candidate"."createdAt"
        OR ("earlier"."createdAt" = "candidate"."createdAt" AND "earlier"."id" < "candidate"."id")
      )
  )
);
CREATE UNIQUE INDEX IF NOT EXISTS "account_provider_account_idx" ON "account" ("providerId", "accountId");
